// ── Saudi time via Intl ──
function getSaudiParts() {
  const now   = new Date();
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Riyadh",
    weekday: "long", month: "long", day: "numeric",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true
  }).formatToParts(now);
  const get = (type) => (parts.find(p => p.type === type) || {}).value || "";
  return {
    day:     get("day"),
    month:   get("month"),
    weekday: get("weekday"),
    hour:    parseInt(get("hour")),
    hh:      get("hour"),
    mm:      get("minute"),
    ss:      get("second")
  };
}

function updateClock() {
  const p         = getSaudiParts();
  const greetWord = p.hour < 12 ? "Good morning" : p.hour < 17 ? "Good afternoon" : "Good evening";
  const userName  = (frappe.session.user_fullname || frappe.session.user || "").split(" ")[0];
  const greetEl   = root_element.querySelector("#ndt-greeting");
  const monthEl   = root_element.querySelector("#ndt-cal-month");
  const dayEl     = root_element.querySelector("#ndt-cal-day");
  const weekdayEl = root_element.querySelector("#ndt-cal-weekday");
  const timeEl    = root_element.querySelector("#ndt-cal-time");

  if (greetEl)   greetEl.textContent   = greetWord + (userName ? ", " + userName : "");
  if (monthEl)   monthEl.textContent   = p.month;
  if (dayEl)     dayEl.textContent     = p.day;
  if (weekdayEl) weekdayEl.textContent = p.weekday;

  if (timeEl) {
    const timeParts = new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Riyadh",
      hour: "2-digit",
      minute: "2-digit", 
      second: "2-digit",
      hour12: true
    }).formatToParts(new Date());

    const hour = timeParts.find(p => p.type === "hour")?.value || "00";
    const minute = timeParts.find(p => p.type === "minute")?.value || "00";
    const second = timeParts.find(p => p.type === "second")?.value || "00";
    const period = timeParts.find(p => p.type === "dayPeriod")?.value || "AM";

    timeEl.textContent = hour + ":" + minute + ":" + second + " " + period.toUpperCase();
  }
}

updateClock();
setInterval(updateClock, 1000);

// ── KPI card links with filters ──
const now = new Date();
const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split("T")[0];
const lastOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split("T")[0];

const kpiCardEl1 = root_element.querySelector("#kpi-link-month");
if (kpiCardEl1) {
  kpiCardEl1.addEventListener("click", (e) => {
    e.preventDefault();
    frappe.set_route("List", "MT Inspection", {
      "date_of_test": ["between", [firstOfMonth, lastOfMonth]]
    });
  });
}

const kpiCardEl2 = root_element.querySelector("#kpi-link-wo");
if (kpiCardEl2) {
  kpiCardEl2.addEventListener("click", (e) => {
    e.preventDefault();
    frappe.set_route("List", "Work Order");
  });
}

const kpiCardEl3 = root_element.querySelector("#kpi-link-pending");
if (kpiCardEl3) {
  kpiCardEl3.addEventListener("click", (e) => {
    e.preventDefault();
    frappe.set_route("List", "MT Inspection", {
      "docstatus": 0
    });
  });
}

const kpiCardEl4 = root_element.querySelector("#kpi-link-accepted");
if (kpiCardEl4) {
  kpiCardEl4.addEventListener("click", (e) => {
    e.preventDefault();
    frappe.set_route("List", "MT Inspection", {
      "docstatus": 1,
      "date_of_test": ["between", [firstOfMonth, lastOfMonth]]
    });
  });
}

const kpiCardEl5 = root_element.querySelector("#kpi-link-equipment");
if (kpiCardEl5) {
  kpiCardEl5.addEventListener("click", (e) => {
    e.preventDefault();
    frappe.set_route("List", "Equipment Master");
  });
}

// ── Shortcuts ──
const shortcuts = {
  "sc-new-wo":    "/app/work-order/new-work-order-1",
  "sc-new-mt":    "/app/mt-inspection/new-mt-inspection-1",
  "sc-all-mt":    "/app/mt-inspection",
  "sc-equipment": "/app/equipment-master",
  "sc-client":    "/app/client-master",
  "sc-project":   "/app/project-master"
};
Object.entries(shortcuts).forEach(([id, route]) => {
  const el = root_element.querySelector("#" + id);
  if (el) el.addEventListener("click", () => frappe.set_route(route));
});

// ── KPI counts ──
function setKPI(id, value, color) {
  const el = root_element.querySelector(id);
  if (!el) return;
  el.textContent = value;
  el.classList.remove("ndt-kpi-loading-val");
  if (color) el.style.color = color;
}

frappe.call({
  method: "frappe.client.get_count",
  args: { doctype: "MT Inspection", filters: [["date_of_test", ">=", firstOfMonth]] },
  callback: (r) => setKPI("#kpi-month", r.message ?? 0, "#2563eb")
});

frappe.call({
  method: "frappe.client.get_count",
  args: { doctype: "Work Order", filters: [] },
  callback: (r) => setKPI("#kpi-wo", r.message ?? 0, "#7c3aed")
});

frappe.call({
  method: "frappe.client.get_count",
  args: { doctype: "MT Inspection", filters: [["docstatus", "=", 0]] },
  callback: (r) => {
    const count = r.message ?? 0;
    setKPI("#kpi-pending", count, count > 0 ? "#b45309" : "#1e1b2e");
    const alertBox  = root_element.querySelector("#ndt-alert");
    const alertText = root_element.querySelector("#ndt-alert-text");
    if (count > 0 && alertBox && alertText) {
      alertText.textContent = count + " inspection" + (count > 1 ? "s" : "") + " awaiting your review.";
      alertBox.classList.add("visible");
    }
  }
});

frappe.call({
  method: "frappe.client.get_count",
  args: { doctype: "MT Inspection", filters: [["docstatus", "=", 1], ["date_of_test", ">=", firstOfMonth]] },
  callback: (r) => setKPI("#kpi-accepted", r.message ?? 0, "#15803d")
});

frappe.call({
  method: "frappe.client.get_count",
  args: { doctype: "Equipment Master" },
  callback: (r) => setKPI("#kpi-equipment", r.message ?? 0, "#0891b2")
});

const alertBtn = root_element.querySelector("#ndt-alert-btn");
if (alertBtn) alertBtn.addEventListener("click", () => frappe.set_route("/app/mt-inspection"));

// ── Recent inspections ──
frappe.call({
  method: "frappe.client.get_list",
  args: {
    doctype: "MT Inspection",
    fields: ["name", "date_of_test", "mt_variant", "docstatus"],
    order_by: "creation desc",
    limit: 5
  },
  callback: (r) => {
    const tbody = root_element.querySelector("#ndt-recent-body");
    if (!tbody) return;
    const rows = r.message || [];
    if (!rows.length) {
      tbody.innerHTML = '<tr><td colspan="4" style="color:#a78bfa;font-size:12px;padding:12px 0;">No inspections yet</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(row => {
      const statusMap = { 0: ["Draft", "badge-draft"], 1: ["Submitted", "badge-submitted"] };
      const [label, cls] = statusMap[row.docstatus] || ["Pending", "badge-pending"];
      const date = row.date_of_test ? new Date(row.date_of_test).toLocaleDateString("en-GB") : "—";
      return `<tr onclick="frappe.set_route('/app/mt-inspection/${row.name}')">
        <td style="font-weight:600;">${row.name || "—"}</td>
        <td style="color:#6b6880;">${date}</td>
        <td>${row.mt_variant || "MT"}</td>
        <td><span class="ndt-badge ${cls}">${label}</span></td>
      </tr>`;
    }).join("");
  }
});

// ── Branch rings ──
const BRANCH_COLORS = [
  "#8b5cf6", "#06b6d4", "#f59e0b", "#10b981",
  "#ef4444", "#3b82f6", "#ec4899", "#14b8a6"
];

function makeSVG(count, pct, color) {
  const R      = 48;
  const stroke = 11;
  const W      = 125;
  const cx     = W / 2;
  const cy     = 54;
  const circ   = Math.PI * R;
  const dash   = ((pct / 100) * circ).toFixed(2);
  return `
    <svg width="${W}" height="62" viewBox="0 0 ${W} 62" style="display:block;overflow:visible;">
      <path d="M ${cx-R} ${cy} A ${R} ${R} 0 0 1 ${cx+R} ${cy}"
            fill="none" stroke="#ede9fe" stroke-width="${stroke}" stroke-linecap="round"/>
      <path d="M ${cx-R} ${cy} A ${R} ${R} 0 0 1 ${cx+R} ${cy}"
            fill="none" stroke="${color}" stroke-width="${stroke}" stroke-linecap="round"
            stroke-dasharray="0 ${circ}"
            style="transition:stroke-dasharray 1s cubic-bezier(0.4,0,0.2,1);"
            data-dash="${dash}" data-circ="${circ}"/>
      <text x="${cx}" y="${cy-10}" text-anchor="middle"
            font-family="Helvetica Neue,Arial,sans-serif" font-size="20" font-weight="700"
            fill="${color}">${count}</text>
      <text x="${cx}" y="${cy+6}" text-anchor="middle"
            font-family="Helvetica Neue,Arial,sans-serif" font-size="9" fill="#6b6880">${pct}% of total</text>
    </svg>
  `;
}

const grid = root_element.querySelector("#ndt-branch-grid");
if (grid) {
  frappe.call({
    method: "frappe.client.get_list",
    args: { doctype: "Branch Master", fields: ["name"], limit: 50, order_by: "name asc" },
    callback: (branchRes) => {
      const branches = (branchRes.message || []).map(b => b.name);
      if (!branches.length) {
        grid.innerHTML = '<p style="font-size:12px;color:#6b6880;margin:0;">No branches found.</p>';
        return;
      }
      const slots = {};
      branches.forEach((name, i) => {
        const color = BRANCH_COLORS[i % BRANCH_COLORS.length];
        const wrap  = document.createElement("div");
        wrap.className = "ndt-ring-wrap";
        wrap.innerHTML = `
          <p class="ndt-ring-name" title="${name}">${name}</p>
          <svg width="125" height="62" viewBox="0 0 125 62" style="display:block;overflow:visible;">
            <path d="M 14 54 A 48 48 0 0 1 111 54"
                  fill="none" stroke="#ede9fe" stroke-width="11" stroke-linecap="round"/>
          </svg>
          <p class="ndt-ring-sub">Loading...</p>
        `;
        wrap.addEventListener("click", () => frappe.set_route("List", "MT Inspection", { branch: name }));
        grid.appendChild(wrap);
        slots[name] = { wrap, color };
      });
      frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "MT Inspection", filters: [] },
        callback: (totalRes) => {
          const total = totalRes.message || 1;
          branches.forEach(name => {
            const { wrap, color } = slots[name];
            frappe.call({
              method: "frappe.client.get_count",
              args: { doctype: "MT Inspection", filters: [["branch", "=", name]] },
              callback: (r) => {
                const count = r.message ?? 0;
                const pct   = Math.round((count / total) * 100);
                const tmp   = document.createElement("div");
                tmp.innerHTML = makeSVG(count, pct, color);
                const newSvg = tmp.querySelector("svg");
                const oldSvg = wrap.querySelector("svg");
                if (oldSvg && newSvg) wrap.replaceChild(newSvg, oldSvg);
                const sub = wrap.querySelector(".ndt-ring-sub");
                if (sub) sub.textContent = "Total inspections";
                setTimeout(() => {
                  const arc = newSvg.querySelector("path[data-dash]");
                  if (arc) arc.setAttribute("stroke-dasharray", `${arc.getAttribute("data-dash")} ${arc.getAttribute("data-circ")}`);
                }, 150);
              }
            });
          });
        }
      });
    }
  });
}

// ── Calendar Modal ──
let currentCalendarDate = new Date();

function renderCalendar(date) {
  const year = date.getFullYear();
  const month = date.getMonth();

  const monthNames = ["January", "February", "March", "April", "May", "June",
                      "July", "August", "September", "October", "November", "December"];
  const titleEl = root_element.querySelector("#ndt-calendar-title");
  if (titleEl) titleEl.textContent = monthNames[month] + " " + year;

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrevMonth = new Date(year, month, 0).getDate();

  const today = new Date();
  const isCurrentMonth = today.getFullYear() === year && today.getMonth() === month;
  const todayDate = today.getDate();

  const daysContainer = root_element.querySelector("#ndt-calendar-days");
  if (!daysContainer) return;

  daysContainer.innerHTML = "";

  for (let i = firstDay - 1; i >= 0; i--) {
    const day = daysInPrevMonth - i;
    const dayEl = document.createElement("div");
    dayEl.className = "ndt-calendar-day other-month";
    dayEl.textContent = day;
    daysContainer.appendChild(dayEl);
  }

  for (let day = 1; day <= daysInMonth; day++) {
    const dayEl = document.createElement("div");
    dayEl.className = "ndt-calendar-day";
    dayEl.textContent = day;

    if (isCurrentMonth && day === todayDate) {
      dayEl.classList.add("today");
    }

    dayEl.addEventListener("click", function() {
      daysContainer.querySelectorAll(".ndt-calendar-day.selected").forEach(el => {
        el.classList.remove("selected");
      });
      if (!dayEl.classList.contains("today")) {
        dayEl.classList.add("selected");
      }
    });

    daysContainer.appendChild(dayEl);
  }

  const totalCells = daysContainer.children.length;
  const remainingCells = 42 - totalCells;
  for (let day = 1; day <= remainingCells; day++) {
    const dayEl = document.createElement("div");
    dayEl.className = "ndt-calendar-day other-month";
    dayEl.textContent = day;
    daysContainer.appendChild(dayEl);
  }
}

const calTrigger = root_element.querySelector("#ndt-cal-widget-trigger");
const calModal = root_element.querySelector("#ndt-calendar-modal");
const calOverlay = root_element.querySelector("#ndt-calendar-overlay");

if (calTrigger && calModal) {
  calTrigger.addEventListener("click", function() {
    currentCalendarDate = new Date();
    renderCalendar(currentCalendarDate);
    calModal.classList.add("active");
  });
}

if (calOverlay && calModal) {
  calOverlay.addEventListener("click", function() {
    calModal.classList.remove("active");
  });
}

const prevBtn = root_element.querySelector("#ndt-cal-prev");
const nextBtn = root_element.querySelector("#ndt-cal-next");

if (prevBtn) {
  prevBtn.addEventListener("click", function() {
    currentCalendarDate.setMonth(currentCalendarDate.getMonth() - 1);
    renderCalendar(currentCalendarDate);
  });
}

if (nextBtn) {
  nextBtn.addEventListener("click", function() {
    currentCalendarDate.setMonth(currentCalendarDate.getMonth() + 1);
    renderCalendar(currentCalendarDate);
  });
}

document.addEventListener("keydown", function(e) {
  if (e.key === "Escape" && calModal && calModal.classList.contains("active")) {
    calModal.classList.remove("active");
  }
});

style:
.ndt-dash {
  background: linear-gradient(135deg, #ede9fe 0%, #fce7f3 40%, #e0f2fe 100%);
  border-radius: 16px;
  padding: clamp(24px, 2.5vw, 32px);
  font-family: 'Helvetica Neue', Arial, sans-serif;
}

.ndt-dash-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: clamp(18px, 2vw, 24px);
  margin-bottom: clamp(16px, 2vw, 20px);
}

.ndt-dash-greeting {
  font-size: clamp(24px, 2.5vw, 28px);
  font-weight: 700;
  color: #1e1b2e;
  margin: 0 0 4px;
  letter-spacing: -0.4px;
}

.ndt-dash-sub {
  font-size: clamp(14px, 1.4vw, 16px);
  color: #6b6880;
  margin: 0;
  font-weight: 500;
}

.ndt-cal-widget {
  background: rgba(255,255,255,0.7);
  border: 0.5px solid rgba(255,255,255,0.9);
  border-radius: 14px;
  overflow: hidden;
  min-width: 96px;
  text-align: center;
  box-shadow: 0 2px 12px rgba(139,92,246,0.10);
  flex-shrink: 0;
}

.ndt-cal-month {
  background: linear-gradient(135deg, #8b5cf6, #a78bfa);
  color: #ffffff;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 7px 16px 6px;
}

.ndt-cal-day {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 36px;
  font-weight: 700;
  color: #1e1b2e;
  line-height: 1;
  padding: 10px 16px 4px;
  letter-spacing: -1px;
}

.ndt-cal-weekday {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: clamp(11px, 1.1vw, 13px);
  font-weight: 600;
  color: #8b5cf6;
  padding: 0 16px 6px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}


.ndt-kpi-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(clamp(150px, 17vw, 180px), 1fr));
  gap: clamp(8px, 1vw, 12px);
  margin-bottom: clamp(16px, 2vw, 20px);
}

.ndt-kpi-card {
  background: rgba(255,255,255,0.55);
  border: 0.5px solid rgba(255,255,255,0.9);
  border-radius: 12px;
  padding: clamp(14px, 1.6vw, 18px) clamp(14px, 1.6vw, 18px);
  cursor: pointer;
  text-decoration: none;
  display: flex;
  flex-direction: column;
  justify-content: center;
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), background 0.2s ease, box-shadow 0.2s ease;
  min-height: clamp(75px, 8vw, 90px);
}

.ndt-kpi-card:hover {
  transform: scale(1.04) translateZ(0);
  -webkit-transform: scale(1.04) translateZ(0);
  background: rgba(255,255,255,0.95);
  box-shadow: 0 4px 20px rgba(139,92,246,0.25);
  text-decoration: none;
}

.ndt-kpi-val {
  font-size: clamp(24px, 2.8vw, 30px);
  font-weight: 700;
  color: #1e1b2e;
  letter-spacing: -0.8px;
  margin: 0 0 4px;
  line-height: 1;
}

.ndt-kpi-lbl {
  font-size: clamp(10px, 1vw, 11px);
  color: #6b6880;
  margin: 0;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  line-height: 1.3;
}

.ndt-kpi-loading-val { color: #c4b5fd; }

.ndt-dash-body {
  display: grid;
  grid-template-columns: 1fr clamp(280px, 26vw, 320px);
  gap: clamp(14px, 1.6vw, 18px);
}

@media (max-width: 1200px) {
  .ndt-dash-body {
    grid-template-columns: 1fr;
  }
}

.ndt-glass-card {
  background: rgba(255,255,255,0.55);
  border: 0.5px solid rgba(255,255,255,0.9);
  border-radius: 14px;
  padding: clamp(18px, 2vw, 24px) clamp(22px, 2.4vw, 28px);
}

.ndt-card-title {
  font-size: clamp(11px, 1.1vw, 13px);
  font-weight: 700;
  color: #1e1b2e;
  margin: 0 0 clamp(16px, 1.8vw, 20px);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.ndt-right-col {
  display: flex;
  flex-direction: column;
  gap: clamp(12px, 1.4vw, 16px);
}

.ndt-alert-glass {
  display: none;
  background: rgba(254,215,170,0.7);
  border: 0.5px solid rgba(251,191,36,0.6);
  border-left: 3px solid #d97706;
  border-radius: 12px;
  padding: clamp(14px, 1.6vw, 18px) clamp(16px, 1.8vw, 20px);
}

.ndt-alert-glass.visible { display: block; }

.ndt-alert-glass-title {
  font-size: clamp(10px, 1vw, 12px);
  font-weight: 700;
  color: #92400e;
  margin: 0 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ndt-alert-glass-text {
  font-size: clamp(12px, 1.2vw, 14px);
  color: #78350f;
  margin: 0 0 10px;
}

.ndt-alert-glass-btn {
  font-size: clamp(11px, 1.1vw, 13px);
  font-weight: 600;
  color: #92400e;
  background: rgba(255,255,255,0.5);
  border: 0.5px solid #d97706;
  border-radius: 6px;
  padding: clamp(5px, 0.6vw, 7px) clamp(12px, 1.4vw, 14px);
  cursor: pointer;
  width: 100%;
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), background 0.2s ease, box-shadow 0.2s ease;
  transform: translateZ(0);
  -webkit-transform: translateZ(0);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  -webkit-font-smoothing: subpixel-antialiased;
  -moz-osx-font-smoothing: auto;
}

.ndt-alert-glass-btn:hover {
  transform: scale(1.04) translateZ(0);
  -webkit-transform: scale(1.04) translateZ(0);
  background: rgba(255,255,255,0.95);
  box-shadow: 0 4px 20px rgba(217,119,6,0.3);
  border-color: #b45309;
}

.ndt-shortcuts-card {
  background: rgba(255,255,255,0.55);
  border: 0.5px solid rgba(255,255,255,0.9);
  border-radius: 14px;
  padding: clamp(16px, 1.8vw, 20px) clamp(18px, 2vw, 22px);
}

.ndt-shortcut-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: clamp(8px, 1vw, 11px) clamp(10px, 1.2vw, 13px);
  margin: 0 clamp(-10px, -1.2vw, -13px);
  border-bottom: 0.5px solid rgba(139,92,246,0.1);
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), background 0.2s ease, box-shadow 0.2s ease;
  transform: translateZ(0);
  -webkit-transform: translateZ(0);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  -webkit-font-smoothing: subpixel-antialiased;
  -moz-osx-font-smoothing: auto;
}

.ndt-shortcut-item:last-child { border-bottom: none; }

.ndt-shortcut-item:hover {
  transform: scale(1.04) translateZ(0);
  -webkit-transform: scale(1.04) translateZ(0);
  background: rgba(255,255,255,0.85);
  box-shadow: 0 4px 20px rgba(139,92,246,0.25);
  border-bottom: 0.5px solid transparent;
}

.ndt-shortcut-label {
  font-size: clamp(12px, 1.2vw, 14px);
  font-weight: 600;
  color: #1e1b2e;
  margin: 0;
}

.ndt-shortcut-tag {
  font-size: clamp(9px, 0.95vw, 11px);
  font-weight: 700;
  padding: clamp(2px, 0.3vw, 3px) clamp(7px, 0.8vw, 9px);
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

