/* Calendar Modal */
.ndt-calendar-modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 9999;
  animation: fadeIn 0.2s ease-out;
}

.ndt-calendar-modal.active {
  display: block;
}

.ndt-calendar-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(30, 27, 46, 0.6);
  backdrop-filter: blur(4px);
}

.ndt-calendar-popup {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: linear-gradient(135deg, #ede9fe 0%, #fce7f3 40%, #e0f2fe 100%);
  border: 0.5px solid rgba(255,255,255,0.9);
  border-radius: 20px;
  padding: 24px;
  box-shadow: 0 20px 60px rgba(139,92,246,0.3);
  width: 90%;
  max-width: 380px;
  animation: slideUp 0.3s cubic-bezier(0.34,1.56,0.64,1);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideUp {
  from { 
    transform: translate(-50%, -45%);
    opacity: 0;
  }
  to { 
    transform: translate(-50%, -50%);
    opacity: 1;
  }
}

.ndt-calendar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.ndt-calendar-title {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  color: #1e1b2e;
  letter-spacing: -0.3px;
}

.ndt-calendar-nav {
  background: rgba(255,255,255,0.6);
  border: 0.5px solid rgba(139,92,246,0.2);
  border-radius: 8px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #8b5cf6;
  cursor: pointer;
  transition: all 0.2s ease;
  font-weight: 600;
}

.ndt-calendar-nav:hover {
  background: rgba(255,255,255,0.95);
  border-color: #8b5cf6;
  transform: scale(1.05);
  box-shadow: 0 2px 8px rgba(139,92,246,0.2);
}

.ndt-calendar-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
  margin-bottom: 8px;
}

.ndt-calendar-weekdays div {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 11px;
  font-weight: 600;
  color: #6b6880;
  text-align: center;
  padding: 8px 0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ndt-calendar-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
}

.ndt-calendar-day {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #1e1b2e;
  text-align: center;
  padding: 10px 0;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  background: rgba(255,255,255,0.4);
}

.ndt-calendar-day:hover {
  background: rgba(255,255,255,0.8);
  transform: scale(1.05);
  box-shadow: 0 2px 8px rgba(139,92,246,0.15);
}

.ndt-calendar-day.other-month {
  color: #a78bfa;
  opacity: 0.5;
}

.ndt-calendar-day.today {
  background: linear-gradient(135deg, #8b5cf6, #a78bfa);
  color: #ffffff;
  font-weight: 700;
  box-shadow: 0 2px 12px rgba(139,92,246,0.4);
}

.ndt-calendar-day.today:hover {
  background: linear-gradient(135deg, #7c3aed, #8b5cf6);
  transform: scale(1.08);
}

.ndt-calendar-day.selected {
  background: rgba(139,92,246,0.2);
  border: 2px solid #8b5cf6;
  font-weight: 700;
}


#ndt-cal-widget-trigger {
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), box-shadow 0.2s ease, background 0.2s ease;
}

#ndt-cal-widget-trigger:hover {
  transform: scale(1.05) translateZ(0);
  -webkit-transform: scale(1.05) translateZ(0);
  box-shadow: 0 6px 24px rgba(139,92,246,0.3);
  background: rgba(255,255,255,0.85);
}

#ndt-cal-widget-trigger:active {
  transform: scale(0.98) translateZ(0);
  -webkit-transform: scale(0.98) translateZ(0);
}
